b.el('next').click();b.write('answer','服务端逐次检查身份和归属，拒绝成员越权，保留管理员访问，不暴露凭据。');b.select('choice',0);b.el('reveal').click();for(const n of b.nodes().filter(n=>n.dataset.check!==undefined)){n.checked=true;n.onchange()}b.select('transfer',1);b.el('finish').click();state=JSON.parse(stored);assert.equal(state.session,null);assert.equal(state.history.length,3);assert(core.valid(state));b.el('next').click();assert.match(b.html(),/今天的到期主题已完成/);
