const topics=[
 {id:'W1',title:'网址 ≠ 运行地点',worry:'我知道 localhost，但不清楚为什么别人打不开。',questions:['你的留言板在自己的电脑上能打开。把 localhost 链接发给朋友却打不开。买一个域名就能解决吗？请解释原因，并说出还缺什么。','朋友在他的电脑上打开 127.0.0.1，为什么没有看到你电脑上的网站？如果要给朋友用，你会先检查什么？'],points:['localhost / 127.0.0.1 指向打开链接的设备自身，所以朋友访问的是朋友自己的设备。','域名是帮助找到服务的名字；买域名不会自动运行程序。','还需要朋友能访问到的运行环境和正在运行的服务。'],transfer:'有人说：“我买好了网址，所以关掉运行网站的电脑也没关系。”你会如何纠正？'},
 {id:'W2',title:'记在本机 ≠ 大家共享',worry:'我以为刷新还有，就说明数据保存好了。',questions:['你写的留言刷新后还在。你说“保存成功，朋友也应该能看到”。这个推论可靠吗？你会怎样验证多人共享和重启后保留？','同一个网站，你在浏览器 A 写的留言，在浏览器 B 没出现。两个浏览器都有 localStorage，为什么不会自动同步？要共享还需要什么？'],points:['localStorage 是当前来源下的浏览器本地数据，不是所有人共用的数据库。','刷新后还在，只能证明当前浏览器保留了数据，不能证明朋友能看到。','共享需要服务端等共同状态来源；要用独立客户端检查，并验证服务重启后是否保留。'],transfer:'你用两个独立浏览器都看到了同一条留言。这是否已经证明服务重启也不会丢？还需要做什么验证？'},
 {id:'W3',title:'隐藏界面 ≠ 具备权限',worry:'我以为隐藏管理员按钮就可以了。',questions:['页面只显示“我的报名”，但修改接口参数就能读取其他成员记录。权限做好了吗？你会在哪里检查、怎样验证？管理员应怎么办？','成员页面没有管理员按钮。有人却直接请求“全部名单”接口成功了。解释问题，并说明应该测试哪些请求，以及如何处理管理员凭据。'],points:['隐藏按钮只是界面行为；服务端必须对每次请求检查身份与数据归属。','要验证成员直接请求别人记录、全部名单都会被拒绝，同时保留管理员正常查看。','可用的管理员凭据不能放在公共页面，即使服务端有检查也不行。'],transfer:'开发者说：“接口已经检查权限，所以把可用管理员凭据写进公共页面也安全。”你会怎样回应？'}
];
const key='shijie-review-v1', $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function day(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function later(n){const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
let data={history:[],drafts:{}},storageOK=true;try{const raw=localStorage.getItem(key);if(raw)data=validate(JSON.parse(raw));}catch(e){storageOK=false;}
function validate(v){if(!v||!Array.isArray(v.history)||!v.drafts||typeof v.drafts!=='object')throw Error();if(v.history.length>10000)throw Error();for(const r of v.history){if(!topics.some(t=>t.id===r.id)||!/^\d{4}-\d{2}-\d{2}$/.test(r.due)||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||typeof r.answer!=='string'||!Number.isInteger(r.score)||r.score<0||r.score>3||!Number.isInteger(r.level)||r.level<0||r.level>3||!['low','mid','high'].includes(r.confidence))throw Error();}for(const [k,d] of Object.entries(v.drafts)){if(!topics.some(t=>t.id===k)||!d||typeof d.answer!=='string'||!['low','mid','high'].includes(d.confidence))throw Error();}return v;}
function persist(){try{localStorage.setItem(key,JSON.stringify(data));storageOK=true;$('#notice').textContent='已保存在此浏览器。';}catch(e){storageOK=false;$('#notice').textContent='浏览器无法保存。当前记录只在本次打开期间有效，请导出备份。';}}
function last(t){return data.history.filter(r=>r.id===t.id).at(-1)}
function due(t){return !last(t)||last(t).due<=day()}
let current=topics.find(due)||topics[0],phase='write';
function map(){ $('#map').innerHTML=topics.map(t=>{const r=last(t);return `<button class="topic ${t===current?'selected':''}" data-id="${t.id}"><strong>${t.id} · ${t.title}</strong><small>${!r?'尚未练习':due(t)?'今天待复习':`下次 ${r.due}`} ${r?`· 最近自评 ${r.score}/3`:''}</small></button>`}).join('');document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{current=topics.find(t=>t.id===b.dataset.id);phase='write';render()});}
function render(){map();const t=current,r=last(t),count=data.history.filter(x=>x.id===t.id).length,d=data.drafts[t.id]||{answer:'',confidence:'mid'};const question=t.questions[count%t.questions.length];$('#workspace').innerHTML=`<span class="badge">${phase==='write'?'01 / 先回忆':phase==='check'?'02 / 对照自评':'03 / 收好薄弱点'}</span><h2>${t.title}</h2>`;
 const el=$('#workspace');
 if(phase==='write'){
 el.innerHTML+=`<p class="muted">来自你的疑问：${t.worry} · 课件 ${t.id}</p>${r&&!due(t)?'<p class="note">今天已完成这一项。可以提前练习，但同一天多练不会增加间隔等级。</p>':''}<div class="question">${question}</div><label for="answer">不用翻笔记，用自己的话解释</label><textarea id="answer" placeholder="先试着说清原因，再说你会怎样验证……">${esc(d.answer)}</textarea><div class="confidence" role="group" aria-label="作答信心">${[['low','还说不清'],['mid','有点把握'],['high','能讲给别人听']].map(([v,l])=>`<label><input type="radio" name="confidence" value="${v}" ${d.confidence===v?'checked':''}>${l}</label>`).join('')}</div><button id="reveal" ${d.answer.trim()?'':'disabled'}>写好了，对照要点</button><p class="muted">答案草稿自动保存。这里没有 AI 评分；不要求与你的措辞一致。</p>${r?`<div class="history">上次练习 ${r.date} · 自评 ${r.score}/3<br>下次请留意：${esc(r.gap||'换个情境，确认还能解释。')}</div>`:''}`;
 const save=()=>{data.drafts[t.id]={answer:$('#answer').value,confidence:document.querySelector('[name=confidence]:checked').value};persist();$('#reveal').disabled=!$('#answer').value.trim()};$('#answer').oninput=save;document.querySelectorAll('[name=confidence]').forEach(x=>x.onchange=save);$('#reveal').onclick=()=>{phase='check';render()};
 }else if(phase==='check'){
 el.innerHTML+=`<div class="question">${question}</div><h3>你刚才的解释</h3><div class="answer">${esc(d.answer)}</div><h3>只勾选你原答案已经表达的要点</h3><p class="muted">读完才想起的，留空即可。意思正确就算，不用逐字相同。</p>${t.points.map((p,i)=>`<label class="rubric"><input type="checkbox" name="point" value="${i}">${p}</label>`).join('')}<p><a href="inputs/课件.md" target="_blank" rel="noopener">核对课件 ${t.id}</a></p><label for="gap">留一句提醒给明天的自己（选填）</label><textarea id="gap" style="min-height:75px" placeholder="我把……和……混在一起；下次要先解释……"></textarea><div class="actions"><button id="finish">记录自评，安排复习</button><button class="secondary" id="back">返回草稿</button></div>`;
