// Offline behavior checks with a minimal DOM substitute; no external packages.
const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const source = fs.readFileSync('app.js', 'utf8');
function boot(saved) {
  const elements = new Map();
  const el = id => {
    if (!elements.has(id)) elements.set(id, {textContent:'', innerHTML:'', value:'', hidden:false, disabled:false});
    return elements.get(id);
  };
  let raw = saved;
  const context = vm.createContext({
    document:{getElementById:el,querySelectorAll:()=>[],querySelector:()=>el('grade2')},
    localStorage:{getItem:()=>raw,setItem:(k,v)=>{raw=v;}},
    confirm:()=>true,alert:()=>{},setTimeout,Date,console
  });
  vm.runInContext(source, context);
  return {el,run:code=>vm.runInContext(code,context),raw:()=>raw};
}
let app=boot();
assert.equal(app.run('state.history.length'),0);
assert.equal(app.run('state.selected'),'W1');
app.el('answer').oninput({target:{value:'朋友的 localhost 指自己；域名不运行程序，需要可达环境。'}});
app.el('reveal').onclick();
const resumed=boot(app.raw());
assert.equal(resumed.run('state.topics.W1.revealed'),true);
assert.match(resumed.run('state.topics.W1.draft'),/localhost/);
resumed.run('complete(2)');
assert.equal(resumed.run('state.history.length'),0,'Strong rating requires all points');
resumed.run('state.topics.W1.checks=[0];complete(1)');
assert.equal(resumed.run('state.history.length'),1);
assert.equal(resumed.run('state.history[0].missing.length'),2);
assert.equal(resumed.run('state.topics.W1.attempt'),1);
assert.ok(resumed.run('state.topics.W1.due>Date.now()+23*3600000'));
assert.equal(resumed.run('state.topics.W1.draft'),'');
resumed.el('next').onclick();
assert.equal(resumed.run('state.selected'),'W2');
assert.equal(boot(resumed.raw()).run('state.history.length'),1);
assert.equal(resumed.run('valid({version:1})'),false);
assert.equal(resumed.run('valid(JSON.parse(JSON.stringify(state)))'),true);
assert.equal(resumed.run('esc("<img onerror=alert(1)>")'),'&lt;img onerror=alert(1)&gt;');
resumed.run('state.selected="W1";render()');
assert.match(resumed.el('workspace').innerHTML,/127\.0\.0\.1/,'Repeat uses a new situation');
const broken=boot('{invalid');
assert.equal(broken.el('storage-warning').hidden,false);
const html=fs.readFileSync('index.html','utf8');
assert.ok(!/https?:\/\//.test(html));
assert.ok(!/\bfetch\s*\(|XMLHttpRequest|WebSocket/.test(source));
